from grow_helpers import *

def dispersal():
    kew=source('Kew: Plant scientists classroom activity pack','https://www.kew.org/sites/default/files/2022-09/LKS2-Plant-scientists-pre-and-post-visit-resources.pdf','Checked September 2026. Seed/fruit structures and dispersal examples. Scientific facts are paraphrased; this investigation is newly authored.')
    rhs=source('RHS: Seed dispersal','https://www.rhs.org.uk/education-learning/school-gardening/resources/curriculum-linked/seed-dispersal','Checked September 2026. Winged and tufted structures support wind dispersal; a fall-time model does not measure outdoor distance.')
    d=base('grow_seed_dispersal_lab','The seed dispersal design lab','Use structures and a fair model to explain a journey','Explain how seed or fruit structures can aid dispersal and evaluate a controlled paper model.',5,['Know that seeds contain an embryo and can develop into plants.','Read repeated measurements in a table.'],['Link a structure to a dispersal mechanism.','Identify what changes and what stays the same in a model test.','Use repeat data without claiming measured outdoor dispersal distance.'],[('dispersal','Movement of seeds away from where they formed.'),('fruit','A flowering-plant structure that develops from the ovary and contains seeds.'),('structure','The shape and arrangement of a part.'),('model','A simplified representation used to explore an idea.'),('control variable','A condition kept the same for a comparison.')],['Shared seed/fruit cards and constructed test results, selected route, pencils; optional calculator.','Optional adult-only demonstration: two equal 4 × 16 cm paper strips; one folded into a compact shape, one with a simple rotor shape; metre rule and clear drop area.'],['Default lesson uses the complete constructed dataset. Label any optional observations separately.','For a rotor: slit the top half lengthways into two equal blades; fold them in opposite directions. Fold the lower half into a narrow body. Keep all paper attached so mass is retained.','Use equal paper stock and original dimensions for both models; do not add clips or change the release height.'],['No climbing, throwing or blowing seeds. If demonstrating, an adult releases models from a marked reachable height above a clear floor.','Use pre-cut paper where needed; no real berries, hooks or seeds are handled or tasted.'],'Use the supplied model design and constructed fall times. Pupils can investigate all decisions on paper without making or dropping anything.',[('A wing means the seed flies using its own power.','Wind-dispersed structures interact with moving air; they do not choose or power a journey.','Ask what moves the air or object.'),('Longer fall time proves a longer real outdoor journey.','It can give wind more time to act, but actual distance also depends on wind, height and other conditions.','Ask what the experiment measured.'),('The plant grew a wing because it wanted to move.','Useful inherited structures exist through evolutionary processes, not an individual plant’s intention.','Ask whether a seed makes a decision.')],['Match structure and mechanism; compare one pair of fall times.','Analyse repeats and explain controls and limitations.','Calculate means and redesign a distance test while separating model from organism.'],[kew,rhs,source('Kew: How plants hitchhike on animal poo','https://www.kew.org/read-and-watch/plant-seed-dispersal-animal-poo','Checked September 2026. Some animals eat fleshy fruit and later pass viable seeds; not every seed survives digestion.')])
    v1=vis('Different structures, different dispersal routes','Two schematic botanical structures are compared without a connecting arrow: sycamore winged fruit with seed-bearing region, and burdock hooked burr enclosing fruits. Structures are simplified and not to scale.',[txt(40,20,920,60,'Structures can change how a seed travels',31,bold=True),rect(60,125,410,320),rect(530,125,410,320),ell(140,275,70,65,'#D6BC8D',ORANGE),ell(190,215,210,75,'#DFEACC',GREEN),line(200,300,385,245,GREEN,False),txt(80,145,370,50,'Sycamore: winged fruit',28),txt(80,370,370,60,'Seed inside the base\nWing interacts with air',25),ell(670,250,120,120,'#DFEACC',GREEN),line(680,255,650,215,GREEN,False),line(650,215,635,230,GREEN,False),line(780,265,825,235,GREEN,False),line(825,235,828,258,GREEN,False),line(782,340,828,362,GREEN,False),line(828,362,807,376,GREEN,False),line(683,350,645,387,GREEN,False),line(645,387,632,368,GREEN,False),txt(550,145,370,50,'Burdock: hooked burr',28),txt(550,395,370,40,'Hooks can attach to fur',25),txt(70,490,860,45,'Dispersal can move the whole fruit containing the seed.',25)])
    v2=vis('Fair paper-model drop comparison','Two paper shapes are released from the same marked height into a clear floor area. The measured quantity is fall time. The models have equal original paper dimensions and retained mass, with shape as the changed feature.',[txt(40,20,920,55,'Change shape; keep the drop conditions',31,bold=True),line(80,135,920,135,BLUE,False),line(80,430,920,430,DARK,False),ell(235,125,35,35,'#DFEACC',GREEN),rect(680,125,85,16,'#DFEACC',GREEN),rect(714,135,16,45,'#DFEACC',GREEN),line(250,190,250,385,BLUE),line(720,195,720,385,BLUE),txt(95,80,810,40,'Release height: 1.5 m in the constructed test',26),txt(65,470,430,65,'Compact paper shape\nMeasure time to floor',27),txt(515,470,430,65,'Rotor paper shape\nMeasure time to floor',27),txt(345,225,270,125,'Same paper mass\nSame release rule\nStill indoor air',25)])
    v3=boxes('What the paper model can tell us',['Observed:\nlonger fall time','Possible effect:\nmore time in air','Not measured:\noutdoor distance'],'Paper models test one feature. Real seed journeys\nalso depend on wind, release height and surroundings.')
    rows=[['Compact paper','0.8','0.9','0.7'],['Rotor paper','1.4','1.5','1.3']]
    ev=[('A • Sycamore','A seed is enclosed in the base of a winged fruit. The wing can slow descent and help wind carry it.'),('B • Burdock','Hooked burrs can attach to animal fur and be carried away before falling off.'),('C • Fleshy fruit','Some animals eat fruit, digest the flesh and later pass surviving seeds elsewhere. Survival is not guaranteed.'),('D • Test method','Constructed test: same paper stock and original 4 × 16 cm size, all paper retained; same 1.5 m release height and rule, still indoor air. Shape changes. Fall time is measured.')]
    d['slides']=[slide('Opening',2,'A seed has no engine',['How could a seed travel away from its parent?','Look for a structure and a force or carrier.'],'Invite a structure-based guess. Avoid intention language such as the seed wants to fly.'),slide('Retrieval',3,'Seed, fruit and a fair comparison',['R1. What can a seed develop into?','R2. Where are seeds found in a flowering plant’s fruit?','R3. Why repeat a measurement?'],'A new plant in suitable conditions; inside or associated with fruit structures depending on species, accept within fruit for core model; repeats reveal variation and strengthen confidence.'),slide('I do',8,'I connect structure to a journey',['A sycamore wing interacts with air.','A burdock hook can attach to fur.','The transported object can include fruit around a seed.'],'Think aloud: I name the structure before the mechanism. A wing supports interaction with air, not self-powered flight. Hooks support attachment, not growth towards an animal. Diagrams are selective.',visual=v1),slide('I do',0,'I design a fair paper comparison',['Change the paper shape.','Keep mass, release height and method the same.','Measure fall time, not imagined travel distance.'],'Shared I do time. Explain exact retained paper and optional rotor instructions from preparation. The constructed test uses no added clip. A clear drop avoids disturbance; pupils may remain entirely on paper.',visual=v2),slide('I do',0,'I keep the claim within the measurement',['A longer descent gives air more time to act.','We measured seconds to the floor.','We did not measure real seeds outdoors.'],'Shared I do time. Think aloud: I cannot turn a fall-time result into a kilometre claim. This is a limited model of structure affecting descent, not proof of every dispersal outcome.',visual=v3),slide('We do',8,'Model design jury',['W1. Match A–C to wind or animal dispersal.','W2. Compare the repeated fall times.','Which shape stayed in the air longer here?'],'A wind; B external animal attachment; C animal ingestion. Rotor times exceed compact in every paired trial; use a pair such as 1.4 vs 0.8 seconds.',table=table(['Constructed model','Trial 1 / s','Trial 2 / s','Trial 3 / s'],rows,'Constructed sample data only; no outdoor distance was measured.')),slide('We do',0,'Detect a broken comparison',['A team changes shape and adds a heavy clip.','Can it attribute the difference only to shape?','Name the repair.'],'Shared We do time. No; mass also changed. Use the same retained paper mass and no extra clip, with matched release conditions.'),slide('We do',0,'Choose the honest caption',['W3. Repair “The rotor proves sycamore seeds always travel farther”.','State the measured result and one limit.'],'The rotor paper model took longer to fall in this setup; actual seed distance depends on wind, structure and environment. Model does not establish all-species ranking.',reveal='In this paper test, the rotor fell more slowly. Real dispersal distance was not measured.'),slide('Hinge',3,'Which quantity was measured?',['Choose the conclusion that fits the test.'],'A correct time; B false nooutdoordistance; C falseintentionalchange.',options=opts([('The time each paper model took to reach the floor.',True,'The units are seconds and the release conditions are stated.'),('How far every real seed travels outside.',False,'The test used paper models indoors and did not measure distance.'),('How much the seeds wanted to move.',False,'Wanting is not a scientific variable for a seed.')]))]
    common_tail(d,['Choose one response route.','Explain a structure and evaluate the model evidence.','Use numerical values and a clear limitation.'],['Name what changed and what stayed the same.','Keep seconds attached to fall-time values.','Do not claim a measured distance.'],['Show one structure–mechanism link.','Check a numerical comparison.','Improve one claim about real seed journeys.'],['E1. Explain how a wing can aid dispersal.','E2. Give evidence from the paper model.','E3. Give one limit of this model.'],'Wing interacts with air/slowsdescent; accurate pairedtimes; paperindoorfalltime notrealoutdoordistance. E4 asksonecontrol.')
    d['pupilPages']=[page('1 • Shared evidence: dispersal jury','All fall times below are constructed sample data, not class observations.',[cards(ev),tb(['Model','Trial 1 / s','Trial 2 / s','Trial 3 / s'],rows),response('W1. Match A–C to a dispersal mechanism. W2. Compare one pair of times.',2),response('W3. Improve the “always travels farther” claim and name a limit.',2)]),page('2 • Supported route: structure and evidence','Use page 1. Point, circle or explain with a short sentence.',[choices('S1. A sycamore wing mainly helps interaction with …',['Air','An animal’s digestive system']),choices('S2. Burdock hooks can help attachment to …',['Animal fur','A pollen tube']),response('S3. Complete: In trial 1, rotor paper took ____ s and compact paper took ____ s. The ____ stayed in the air longer.',3),response('S4. Name one condition kept the same in the paper test.',3),response('S5. Does this prove real outdoor travel distance? Explain.',3)]),page('3 • Standard route: design jury report','Use the shared evidence and state exactly what was measured.',[response('N1. Explain a wing, hook and fleshy-fruit dispersal route.',4),response('N2. Compare the two models using two pairs of times and units.',4),response('N3. Name the changed variable, two controls and the measured quantity.',4),response('N4. Explain why adding a clip to one model weakens a shape-only comparison.',3),response('N5. Give a bounded conclusion and one model limitation.',3)]),page('4 • Stretch route: design a stronger test','Do not confuse fall time with distance.',[response('T1. Calculate the mean fall time for each paper shape and compare them. Show working.',4),response('T2. Explain why the model supports a possible role for a wing but cannot prove every real seed travels farther.',4),response('T3. Design a later model test of horizontal distance using controlled airflow. Name the change, two controls, repeated measurement and units.',4),response('T4. Evaluate “plants grew hooks because they wanted animals to carry them”. Write a scientific replacement without intention.',4)]),page('5 • Exit and reflection','Use evidence and an honest limit.',[response('E1. Explain one structure–dispersal link.',3),response('E2. Compare two fall times from page 1 using units.',3),response('E3. What does the paper model not establish?',3),response('E4. Name a control and explain its purpose.',3),response('Reflection. What should the next model measure?',3)])]
    d['answers']=[ans('R1–R3','New plant under suitable conditions; seeds are associated with fruit structures, core example inside fruit; repeats show variation and support a more reliable comparison.'),ans('W1–W3 / design fault','A wind; B external animal attachment; C animal ingestion. Rotor exceeds compact in all trial pairs: 1.4/0.8, 1.5/0.9, 1.3/0.7 seconds. Adding a clip changes mass as well as shape; match mass. W3 bounded paper fall-time conclusion, not all real seed distances.'),ans('Hinge A–C','A correct. B no distance measured. C intention is not the measured variable.'),ans('S1–S5','Air; animal fur; 1.4, 0.8, rotor; any stated control; no, paper indoor descent time is not an outdoor distance measurement.'),ans('N1–N5','Wing interacts with air/slows descent; hook attaches to fur; animals can ingest fruit and later pass surviving seeds. N2 correct paired values/units. N3 shape changes; mass, release height/rule and airflow controlled; time to floor measured. N4 added mass is another changed factor. N5 rotor took longer in this setup; limits include paper structure, indoor still air and no distance measurement.'),ans('T1–T4','T1 compact (0.8+0.9+0.7)/3=0.8 s; rotor (1.4+1.5+1.3)/3=1.4 s; difference0.6 s. T2 longer descent may allow more wind influence, but actual distance depends on many conditions. T3 vary one shape under fixed airflow setting, release height and model mass; repeat and measure horizontal landing distance in cm. It is a planning task, not an instruction to improvise a fan practical now. T4 useful inherited structures can aid dispersal; individuals do not develop them because they want a ride. Evolutionary detail is optional.'),ans('E1–E4 / assessment','Correct structure–mechanism link; accurate pair and seconds; not real outdoor distance; relevant control/purpose. Secure: mechanism, fair variable distinction, numerical result and limit. Re-teach overclaim by underlining seconds and asking what was actually measured. Reflection accepts a precise next variable or measurement.')]
    interactive(d,'Dispersal jury: structure, method and claim',[( 'Which structure can attach to animal fur?', [('A hooked burdock burr.',True,'Hooks support attachment and transport on an animal.'),('Any wing simply because it is a wing.',False,'A wing mainly changes interaction with air; the hook evidence supports attachment.')],'Match structure to mechanism for W1.'),('A team adds a clip to only one paper model. Is shape the only change?',[('No; mass changes too.',True,'The comparison needs matched retained mass if it isolates shape.'),('Yes; clips cannot affect descent.',False,'Changing mass can change the motion; it is another variable.')],'Repair the method before interpreting a shape effect.'),('Which claim fits the supplied times?',[('Rotor paper stayed in the air longer in this setup.',True,'Every rotor trial took longer to reach the floor.'),('All real winged seeds always travel farther outdoors.',False,'Real distance was not measured and other conditions matter.')],'Use a time pair and a limit for W2–W3.')])
    finish(d,['The default investigation is fully paper-based. Any optional adult demonstration is a separate observation, labelled as such; it must not overwrite the constructed sample record.','A sycamore dispersal unit is a winged fruit containing a seed; burdock burrs carry fruits/seeds. Keep the seed-versus-fruit distinction accurate without overloading the supported route.','Interactive decisions use the same structures, test conditions and times as W1–W3.'])

if __name__=='__main__':dispersal()
